// Flashcards de conceitos — Transpetro 2026 (Cesgranrio). Um conceito por cartão; o verso usa " • " para separar os tópicos.
const FLASHCARDS = [
{"m": "Português", "t": "Crase — regra-base", "d": "Fusão da preposição \"a\" (exigida por um termo) com o artigo \"a\" (aceito pela palavra feminina seguinte) • Teste: troque por um masculino; se virar \"ao\", há crase • Ex.: Fui à reunião (fui ao encontro)."},
{"m": "Português", "t": "Crase obrigatória — locuções", "d": "Locuções adverbiais, prepositivas e conjuntivas femininas: às vezes, à noite, às pressas, à medida que, à custa de, à procura de • Também na expressão \"à moda de\" mesmo oculta: bife à (moda) milanesa."},
{"m": "Português", "t": "Crase com horas", "d": "Há crase na indicação de hora determinada: às 8h, à 1h, das 14h às 18h • Não há crase com \"para\", \"desde\", \"após\" antes da hora (desde as 8h, após as 10h)."},
{"m": "Português", "t": "Crase proibida", "d": "Antes de palavra masculina, de verbo, de pronome pessoal, de tratamento (V.Sa., você) e indefinido; diante de \"a\" no singular seguido de plural (a pessoas); entre palavras repetidas (cara a cara, gota a gota)."},
{"m": "Português", "t": "Crase facultativa", "d": "Antes de pronome possessivo feminino singular (à/a minha mãe), de nome próprio feminino de pessoa (à/a Maria) e depois de \"até\" (até à/a porta)."},
{"m": "Português", "t": "Crase com nomes de lugar", "d": "\"Volto DA, crase HÁ; volto DE, crase pra quê?\" • Vou à Bahia (volto da Bahia) • Vou a Roma (volto de Roma) • Com especificador volta a crase: à Roma antiga."},
{"m": "Português", "t": "Crase com \"aquele(s), aquela(s), aquilo\"", "d": "Há crase quando o termo anterior exige a preposição \"a\": Refiro-me àquele contrato • Assisti àquilo • Sem exigência de \"a\", não há: Vi aquele contrato."},
{"m": "Português", "t": "Haver no sentido de existir/acontecer", "d": "Verbo impessoal: fica no singular e contamina o auxiliar • Houve problemas • Deve haver soluções (nunca \"devem haver\") • ⚠ \"Existir\" concorda: Existem soluções."},
{"m": "Português", "t": "Fazer indicando tempo decorrido ou clima", "d": "Verbo impessoal, sempre no singular: Faz dez anos • Vai fazer dois meses • Fazia dias quentes."},
{"m": "Português", "t": "Voz passiva sintética (VTD + se)", "d": "O verbo concorda com o sujeito paciente: Vendem-se casas • Alugam-se salas • Teste: \"Casas são vendidas\"."},
{"m": "Português", "t": "Índice de indeterminação do sujeito (VTI/VI + se)", "d": "O verbo fica no singular: Precisa-se de técnicos • Trata-se de questões • Vive-se bem aqui • A preposição denuncia o VTI."},
{"m": "Português", "t": "Sujeito posposto ao verbo", "d": "O verbo concorda normalmente com o sujeito mesmo depois dele: Chegaram os relatórios • Faltam três dias • ⚠ Pegadinha clássica Cesgranrio."},
{"m": "Português", "t": "Concordância com \"a maioria de / grande parte de\" + plural", "d": "Verbo no singular (com o núcleo) ou no plural (com o especificador): A maioria dos empregados aprovou/aprovaram."},
{"m": "Português", "t": "Anexo, obrigado, mesmo, quite, incluso", "d": "Adjetivos: concordam com o substantivo • As planilhas seguem anexas • Ela disse: obrigada • Eles mesmos • ⚠ \"Em anexo\" é invariável."},
{"m": "Português", "t": "\"Meio\" e \"bastante\"", "d": "Advérbio (modifica adjetivo/verbo) = invariável: Ela está meio cansada; Eles falam bastante • Adjetivo/numeral (com substantivo) = varia: meia hora; bastantes motivos."},
{"m": "Português", "t": "\"É proibido / é necessário / é bom\"", "d": "Sem artigo = invariável: É proibido entrada • Com artigo/determinante = concorda: É proibida a entrada."},
{"m": "Português", "t": "Regência — assistir", "d": "Ver/presenciar: VTI com \"a\" (assisti ao filme) • Ajudar/prestar assistência: VTD (o médico assistiu o paciente) • Caber direito: VTI (assiste ao réu o direito)."},
{"m": "Português", "t": "Regência — aspirar / visar", "d": "Aspirar = desejar → \"a\" (aspira ao cargo); = cheirar → direto • Visar = pretender → \"a\" (visa ao lucro); = mirar ou dar visto → direto (visou o cheque)."},
{"m": "Português", "t": "Regência — preferir", "d": "Prefere-se uma coisa A outra: Prefiro chá a café • ⚠ Errado: \"prefiro mais\", \"prefiro do que\"."},
{"m": "Português", "t": "Regência — implicar", "d": "No sentido de acarretar/ter como consequência: VTD, sem preposição • A decisão implica custos (não \"implica em\")."},
{"m": "Português", "t": "Regência — obedecer, responder, chegar, ir", "d": "Obedecer/desobedecer a • Responder a (carta, pergunta) • Chegar/ir a um lugar (cheguei ao porto, não \"no porto\")."},
{"m": "Português", "t": "Regência — esquecer / lembrar", "d": "Sem pronome: VTD (esqueci o prazo) • Com pronome: VTI com \"de\" (esqueci-me do prazo) • ⚠ Errado: \"esqueci do prazo\"."},
{"m": "Português", "t": "Regência — pagar e perdoar", "d": "Coisa = objeto direto; pessoa = objeto indireto: Paguei a conta ao fornecedor • Perdoou a dívida ao cliente."},
{"m": "Português", "t": "Vírgula — sujeito e verbo", "d": "Nunca se separa sujeito de verbo nem verbo de complemento por uma única vírgula • ⚠ Erro mais cobrado: \"Os gestores da empresa, aprovaram\"."},
{"m": "Português", "t": "Vírgula — adjunto adverbial deslocado", "d": "Termo adverbial no início ou meio da frase: vírgula facultativa se curto, recomendada se longo • Ontem(,) o navio atracou."},
{"m": "Português", "t": "Vírgula — oração adjetiva explicativa x restritiva", "d": "Explicativa (generaliza) vem entre vírgulas: Os técnicos, que estudaram, passaram (todos) • Restritiva (particulariza) sem vírgula: Os técnicos que estudaram passaram (só alguns)."},
{"m": "Português", "t": "Vírgula — aposto e vocativo", "d": "Aposto explicativo e vocativo são sempre isolados por vírgula: A Transpetro, subsidiária da Petrobras, … • Senhores, iniciemos."},
{"m": "Português", "t": "Vírgula antes de \"e\"", "d": "Não se usa com sujeito único e mesmas funções • Usa-se quando as orações têm sujeitos diferentes, quando o \"e\" tem valor adversativo (= mas) ou quando se repete (polissíndeto)."},
{"m": "Português", "t": "Conectivos adversativos", "d": "Oposição/contraste: mas, porém, contudo, todavia, entretanto, no entanto • Coordenam orações independentes."},
{"m": "Português", "t": "Conectivos concessivos", "d": "Admitem um fato contrário que não impede o outro: embora, ainda que, mesmo que, conquanto, se bem que, apesar de • ⚠ Pedem verbo no subjuntivo (embora seja)."},
{"m": "Português", "t": "Conectivos conclusivos", "d": "Logo, portanto, por isso, assim, então, pois (POSPOSTO ao verbo, entre vírgulas: Estudou; passará, pois, no concurso)."},
{"m": "Português", "t": "Conectivos explicativos e causais", "d": "Explicativos: pois (anteposto), porque, que (após imperativo: Saia, que vai chover) • Causais: porque, como (no início), já que, visto que, uma vez que."},
{"m": "Português", "t": "Conectivos condicionais e finais", "d": "Condicionais: se, caso, desde que (+ subjuntivo), contanto que • Finais (objetivo): para que, a fim de que, a fim de."},
{"m": "Português", "t": "\"Que\" — pronome relativo x conjunção integrante", "d": "Relativo retoma um antecedente e pode virar \"o qual\" (o contrato que assinei) • Integrante inicia oração substantiva e pode virar \"isso\" (Espero que venha = Espero isso)."},
{"m": "Português", "t": "Por que / Porque / Por quê / Porquê", "d": "Por que: pergunta ou \"pelo qual\" • Porque: resposta/causa • Por quê: fim de frase/antes de pausa • Porquê: substantivo, com artigo (o porquê)."},
{"m": "Português", "t": "Mal x mau / Senão x se não", "d": "Mal opõe-se a bem (advérbio/substantivo); mau opõe-se a bom (adjetivo) • Senão = do contrário/exceto; se não = caso não."},
{"m": "Português", "t": "Acerca de / há cerca de / a cerca de", "d": "Acerca de = sobre • Há cerca de = faz aproximadamente (tempo passado) ou existem aproximadamente • A cerca de = a uma distância aproximada."},
{"m": "Português", "t": "Onde x aonde / A fim de x afim", "d": "Onde = lugar em que (estático); aonde = a que lugar (movimento: aonde vai?) • A fim de = finalidade; afim = semelhante, afinidade."},
{"m": "Português", "t": "Acentuação — Novo Acordo", "d": "Sem acento: ditongos abertos ÉI/ÓI em paroxítonas (ideia, heroico), hiato OO/EE (voo, leem), para (verbo), pelo • Mantêm: pôr (verbo), pôde (passado), têm/vêm (plural)."},
{"m": "Português", "t": "Parônimos — ratificar/retificar, eminente/iminente", "d": "Ratificar = confirmar; retificar = corrigir • Eminente = notável; iminente = prestes a ocorrer."},
{"m": "Português", "t": "Parônimos — descriminar/discriminar, infligir/infringir", "d": "Descriminar = tirar a culpa; discriminar = separar/distinguir • Infligir = aplicar (pena); infringir = violar (regra)."},
{"m": "Português", "t": "Homônimos — cessão, sessão, seção", "d": "Cessão = ato de ceder • Sessão = reunião/tempo de duração • Seção (secção) = divisão, departamento."},
{"m": "Português", "t": "Denotação x conotação", "d": "Denotação: sentido literal, de dicionário • Conotação: sentido figurado, contextual • Cesgranrio pede o sinônimo que preserva o sentido NO CONTEXTO."},
{"m": "Português", "t": "Mecanismos de coesão referencial", "d": "Retomada de termos por pronomes, sinônimos, hiperônimos e elipse • Anáfora retoma algo já dito; catáfora antecipa algo que virá."},
{"m": "Matemática e Raciocínio Lógico", "t": "Negação de \"Todo A é B\"", "d": "\"Algum A não é B\" (existe pelo menos um que não é) • ⚠ Não é \"Nenhum A é B\"."},
{"m": "Matemática e Raciocínio Lógico", "t": "Negação de \"Nenhum A é B\"", "d": "\"Algum A é B\" (existe pelo menos um que é)."},
{"m": "Matemática e Raciocínio Lógico", "t": "Negação de p ∧ q (e)", "d": "~p ∨ ~q — nega as duas e troca \"e\" por \"ou\" (Lei de De Morgan)."},
{"m": "Matemática e Raciocínio Lógico", "t": "Negação de p ∨ q (ou)", "d": "~p ∧ ~q — nega as duas e troca \"ou\" por \"e\" (Lei de De Morgan)."},
{"m": "Matemática e Raciocínio Lógico", "t": "Negação de p → q (Se p, então q)", "d": "p ∧ ~q — mantém a primeira, E, nega a segunda (regra do \"MA-NÉ\")."},
{"m": "Matemática e Raciocínio Lógico", "t": "Equivalências de p → q", "d": "~q → ~p (contrapositiva: inverte e nega) • ~p ∨ q (nega a primeira OU mantém a segunda)."},
{"m": "Matemática e Raciocínio Lógico", "t": "Quando a condicional p → q é falsa", "d": "Somente quando p é verdadeira e q é falsa (V → F) • Em todos os outros casos é verdadeira."},
{"m": "Matemática e Raciocínio Lógico", "t": "Bicondicional p ↔ q", "d": "Verdadeira quando p e q têm o mesmo valor (V-V ou F-F) • Equivale a (p → q) ∧ (q → p)."},
{"m": "Matemática e Raciocínio Lógico", "t": "Tautologia x contradição x contingência", "d": "Tautologia: sempre V • Contradição: sempre F • Contingência: depende dos valores • Nº de linhas da tabela-verdade = 2ⁿ (n proposições)."},
{"m": "Matemática e Raciocínio Lógico", "t": "Permutação simples", "d": "Pₙ = n! — ordena todos os n elementos distintos • Anagramas de AMOR = 4! = 24."},
{"m": "Matemática e Raciocínio Lógico", "t": "Permutação com repetição", "d": "n! ÷ (a!·b!·…) — divide pelos fatoriais das repetições • ARARA = 5!/(3!·2!) = 10."},
{"m": "Matemática e Raciocínio Lógico", "t": "Arranjo simples", "d": "A(n,p) = n!/(n−p)! — escolher p de n em que a ORDEM importa (cargos diferentes, senhas)."},
{"m": "Matemática e Raciocínio Lógico", "t": "Combinação simples", "d": "C(n,p) = n!/[p!(n−p)!] — escolher p de n em que a ordem NÃO importa (comissões, grupos)."},
{"m": "Matemática e Raciocínio Lógico", "t": "Princípio fundamental da contagem", "d": "Etapas independentes: multiplicam-se as possibilidades • 3 camisas × 2 calças = 6 combinações."},
{"m": "Matemática e Raciocínio Lógico", "t": "Probabilidade clássica", "d": "P = casos favoráveis ÷ casos possíveis • Vale entre 0 e 1 • P(não A) = 1 − P(A)."},
{"m": "Matemática e Raciocínio Lógico", "t": "Probabilidade da união", "d": "P(A ∪ B) = P(A) + P(B) − P(A ∩ B) • Se mutuamente exclusivos, P(A ∩ B) = 0."},
{"m": "Matemática e Raciocínio Lógico", "t": "Eventos independentes / condicional", "d": "Independentes: P(A ∩ B) = P(A)·P(B) • Condicional: P(A|B) = P(A ∩ B) ÷ P(B)."},
{"m": "Matemática e Raciocínio Lógico", "t": "Média, mediana e moda", "d": "Média = soma ÷ quantidade • Mediana = valor central dos dados ORDENADOS (n par: média dos dois centrais) • Moda = valor mais frequente."},
{"m": "Matemática e Raciocínio Lógico", "t": "Variância e desvio-padrão", "d": "Variância = média dos quadrados dos desvios em relação à média • Desvio-padrão = √variância (mesma unidade dos dados) • Somar constante não altera; multiplicar por k multiplica o DP por |k|."},
{"m": "Matemática e Raciocínio Lógico", "t": "Razão e proporção — propriedade fundamental", "d": "a/b = c/d ⇔ a·d = b·c (produto dos meios = produto dos extremos)."},
{"m": "Matemática e Raciocínio Lógico", "t": "Grandezas direta e inversamente proporcionais", "d": "Diretas: uma dobra, a outra dobra (divide-se em partes proporcionais aos números) • Inversas: uma dobra, a outra cai pela metade (proporcional aos inversos)."},
{"m": "Matemática e Raciocínio Lógico", "t": "Regra de três composta", "d": "Coloque a incógnita, compare cada grandeza com ela (direta/inversa), inverta as inversas e multiplique as razões."},
{"m": "Matemática e Raciocínio Lógico", "t": "MMC x MDC — quando usar", "d": "MMC: eventos que voltam a coincidir (\"de novo juntos\") • MDC: dividir em partes iguais do MAIOR tamanho possível • MMC × MDC = a × b."},
{"m": "Matemática e Raciocínio Lógico", "t": "Função afim f(x) = ax + b", "d": "Gráfico: reta • a = coeficiente angular (a>0 crescente) • b = onde corta o eixo y • Raiz: x = −b/a."},
{"m": "Matemática e Raciocínio Lógico", "t": "Função quadrática f(x) = ax² + bx + c", "d": "Parábola • a>0 concavidade para cima (mínimo) • Δ = b² − 4ac • Vértice: xv = −b/2a ; yv = −Δ/4a • Raízes: (−b ± √Δ)/2a."},
{"m": "Matemática e Raciocínio Lógico", "t": "Discriminante Δ", "d": "Δ > 0: duas raízes reais distintas • Δ = 0: uma raiz (dupla) • Δ < 0: nenhuma raiz real."},
{"m": "Matemática e Raciocínio Lógico", "t": "Propriedades dos logaritmos", "d": "log(a·b) = log a + log b • log(a/b) = log a − log b • log aⁿ = n·log a • logₐ a = 1 • logₐ 1 = 0 • Mudança de base: logₐ b = log b / log a."},
{"m": "Matemática e Raciocínio Lógico", "t": "Progressão aritmética (PA)", "d": "aₙ = a₁ + (n−1)·r • Soma: Sₙ = (a₁ + aₙ)·n/2."},
{"m": "Matemática e Raciocínio Lógico", "t": "Progressão geométrica (PG)", "d": "aₙ = a₁·qⁿ⁻¹ • Soma finita: Sₙ = a₁(qⁿ − 1)/(q − 1) • Soma infinita (|q|<1): a₁/(1 − q)."},
{"m": "Matemática e Raciocínio Lógico", "t": "Teorema de Pitágoras", "d": "Hipotenusa² = cateto² + cateto² • Ternos comuns: 3-4-5, 5-12-13, 8-15-17."},
{"m": "Matemática e Raciocínio Lógico", "t": "Áreas de figuras planas", "d": "Retângulo b·h • Triângulo b·h/2 • Trapézio (B+b)·h/2 • Losango D·d/2 • Círculo π·r² • Comprimento da circunferência 2πr."},
{"m": "Matemática e Raciocínio Lógico", "t": "Volumes de sólidos", "d": "Prisma/cilindro: área da base × altura (cilindro πr²h) • Pirâmide/cone: (área da base × altura)/3 • Esfera: 4/3·π·r³."},
{"m": "Matemática e Raciocínio Lógico", "t": "Conjuntos — união com interseção", "d": "n(A ∪ B) = n(A) + n(B) − n(A ∩ B) • Diagrama de Venn: preencha sempre de dentro (interseção) para fora."},
{"m": "Matemática e Raciocínio Lógico", "t": "Conjuntos numéricos", "d": "ℕ ⊂ ℤ ⊂ ℚ ⊂ ℝ • Racionais: frações (inclui dízimas periódicas) • Irracionais: dízimas não periódicas (√2, π) • ℝ = ℚ ∪ Irracionais."},
{"m": "Matemática e Raciocínio Lógico", "t": "Funções trigonométricas — valores notáveis", "d": "sen30=1/2, sen45=√2/2, sen60=√3/2 • cos é o inverso (cos60=1/2) • tg = sen/cos (tg45=1) • sen²x + cos²x = 1."},
{"m": "Matemática Financeira", "t": "Juros simples", "d": "J = C·i·t • M = C(1 + i·t) • Juros incidem sempre sobre o capital inicial (crescimento linear) • ⚠ Taxa e tempo na mesma unidade."},
{"m": "Matemática Financeira", "t": "Juros compostos", "d": "M = C(1 + i)ⁿ • Juros sobre juros (crescimento exponencial) • Para n > 1 período, rende mais que o simples; para n < 1, rende menos."},
{"m": "Matemática Financeira", "t": "Taxas proporcionais", "d": "Regime simples: basta dividir/multiplicar • 12% a.a. ↔ 1% a.m."},
{"m": "Matemática Financeira", "t": "Taxas equivalentes", "d": "Regime composto: (1 + i₁)ⁿ¹ = (1 + i₂)ⁿ² • 1% a.m. ≠ 12% a.a. (equivale a ≈ 12,68% a.a.)."},
{"m": "Matemática Financeira", "t": "Taxa nominal x efetiva", "d": "Nominal: período da taxa ≠ período de capitalização (ex.: 24% a.a. capitalizados mensalmente) • Efetiva: converta para 2% a.m. e capitalize: (1,02)¹² − 1 ≈ 26,82% a.a."},
{"m": "Matemática Financeira", "t": "Aumentos e descontos sucessivos", "d": "Multiplique os fatores: +20% e −20% → 1,2 × 0,8 = 0,96 (queda de 4%) • ⚠ Nunca some as porcentagens."},
{"m": "Matemática Financeira", "t": "Fator de aumento / redução", "d": "Aumento de x% → multiplicar por (1 + x/100) • Redução de x% → multiplicar por (1 − x/100) • Ex.: +15% = ×1,15; −30% = ×0,70."},
{"m": "Matemática Financeira", "t": "Variação percentual", "d": "(Valor final − valor inicial) ÷ valor inicial × 100 • A base é SEMPRE o valor inicial."},
{"m": "Matemática Financeira", "t": "Desconto comercial simples (por fora / bancário)", "d": "D = N·d·n (incide sobre o valor NOMINAL/futuro) • A = N(1 − d·n) • É o desconto usado em duplicatas e bancos."},
{"m": "Matemática Financeira", "t": "Desconto racional simples (por dentro)", "d": "Incide sobre o valor ATUAL: A = N ÷ (1 + i·n) • D = N − A • Sempre menor que o comercial na mesma taxa."},
{"m": "Matemática Financeira", "t": "Desconto racional composto", "d": "A = N ÷ (1 + i)ⁿ • É a operação de trazer um valor futuro a valor presente."},
{"m": "Matemática Financeira", "t": "Taxa efetiva de um desconto comercial", "d": "i = d ÷ (1 − d·n) • Ex.: d = 5% a.m. por 2 meses → paga-se 90 para receber 100 → taxa efetiva ≈ 11,1% no período."},
{"m": "Matemática Financeira", "t": "Sistema Price (francês)", "d": "Prestações CONSTANTES • Juros decrescentes e amortização crescente ao longo do tempo."},
{"m": "Matemática Financeira", "t": "SAC — Sistema de Amortização Constante", "d": "Amortização CONSTANTE (dívida ÷ nº de parcelas) • Juros e prestações DECRESCENTES (caem em progressão aritmética) • 1ª prestação é maior que no Price."},
{"m": "Matemática Financeira", "t": "Sistema americano de amortização", "d": "Paga-se só juros nos períodos • O principal é devolvido integralmente na última parcela."},
{"m": "Matemática Financeira", "t": "Valor presente líquido (VPL)", "d": "Soma dos fluxos trazidos a valor presente pela taxa mínima de atratividade menos o investimento inicial • VPL > 0: projeto viável."},
{"m": "Matemática Financeira", "t": "Taxa interna de retorno (TIR)", "d": "Taxa que torna o VPL igual a zero • Aceita-se o projeto se TIR > taxa mínima de atratividade (TMA)."},
{"m": "Matemática Financeira", "t": "Payback", "d": "Tempo necessário para recuperar o investimento inicial com os fluxos de caixa • Simples (sem desconto) ou descontado (a valor presente)."},
{"m": "Matemática Financeira", "t": "Equivalência de capitais", "d": "Dois capitais são equivalentes se, levados à mesma data focal pela mesma taxa, têm o mesmo valor • No composto, qualquer data focal serve."},
{"m": "Matemática Financeira", "t": "Juros exatos x comerciais", "d": "Comerciais (ordinários): ano de 360 dias, mês de 30 • Exatos: ano civil de 365 (366) dias."},
{"m": "Matemática Financeira", "t": "Montante de uma série uniforme (postecipada)", "d": "VF = PMT·[(1 + i)ⁿ − 1]/i • Valor presente: VP = PMT·[1 − (1 + i)⁻ⁿ]/i."},
{"m": "Matemática Financeira", "t": "Inflação e taxa real (Fisher)", "d": "(1 + aparente) = (1 + real)·(1 + inflação) • Ex.: rendeu 10% com inflação de 4% → real = 1,10/1,04 − 1 ≈ 5,77%."},
{"m": "Contabilidade", "t": "Sequência da DRE (Lei 6.404, art. 187)", "d": "1) Receita bruta • 2) (−) Deduções (devoluções, abatimentos, impostos sobre vendas) = Receita líquida • 3) (−) CMV/CPV/CSP = Lucro bruto • 4) (−) Despesas operacionais (vendas, administrativas) ± outras receitas/despesas ± resultado financeiro = Resultado antes do IR/CSLL • 5) (−) IR e CSLL • 6) (−) Participações = Lucro líquido."},
{"m": "Contabilidade", "t": "Receita líquida", "d": "Receita bruta menos deduções: devoluções e cancelamentos, abatimentos e descontos incondicionais, e tributos sobre vendas (ICMS, ISS, PIS, Cofins)."},
{"m": "Contabilidade", "t": "Lucro bruto", "d": "Receita líquida menos o custo das mercadorias vendidas (CMV), dos produtos vendidos (CPV) ou dos serviços prestados (CSP)."},
{"m": "Contabilidade", "t": "CMV — fórmula", "d": "CMV = Estoque inicial + Compras líquidas − Estoque final."},
{"m": "Contabilidade", "t": "Equação fundamental do patrimônio", "d": "Ativo = Passivo + Patrimônio Líquido • PL = Ativo − Passivo (situação líquida)."},
{"m": "Contabilidade", "t": "Grupos do Ativo (ordem de liquidez decrescente)", "d": "Ativo circulante • Ativo não circulante: realizável a longo prazo, investimentos, imobilizado e intangível."},
{"m": "Contabilidade", "t": "Grupos do Passivo e do PL", "d": "Passivo circulante • Passivo não circulante • PL: capital social, reservas de capital, ajustes de avaliação patrimonial, reservas de lucros, (−) ações em tesouraria, (−) prejuízos acumulados."},
{"m": "Contabilidade", "t": "Critério circulante x não circulante", "d": "Circulante: realizável/exigível até o término do exercício seguinte (12 meses) • Não circulante: após esse prazo • ⚠ Ciclo operacional maior que 12 meses usa o ciclo."},
{"m": "Contabilidade", "t": "Natureza das contas (saldo)", "d": "Devedora: ativo e despesas (aumentam a débito) • Credora: passivo, PL e receitas (aumentam a crédito) • Contas redutoras têm saldo oposto ao grupo (ex.: depreciação acumulada é credora no ativo)."},
{"m": "Contabilidade", "t": "Método das partidas dobradas", "d": "Todo lançamento tem débito e crédito de igual valor • Não há débito sem crédito correspondente • Soma dos débitos = soma dos créditos."},
{"m": "Contabilidade", "t": "Regime de competência", "d": "Receitas e despesas são reconhecidas no período em que ocorrem (fato gerador), independentemente de recebimento ou pagamento • É o exigido pela contabilidade societária."},
{"m": "Contabilidade", "t": "Regime de caixa", "d": "Reconhece receitas e despesas somente quando há recebimento ou pagamento • Usado na DFC e em entidades públicas/pequenas, não na DRE societária."},
{"m": "Contabilidade", "t": "Princípio da entidade", "d": "O patrimônio da empresa não se confunde com o dos sócios • Despesa pessoal do sócio não é despesa da empresa."},
{"m": "Contabilidade", "t": "Princípio da continuidade", "d": "Presume-se que a entidade continuará operando no futuro previsível • Se houver descontinuidade, os ativos passam a ser avaliados por valor de realização."},
{"m": "Contabilidade", "t": "Princípio da prudência (conservadorismo)", "d": "Entre alternativas igualmente válidas, adota-se o menor valor para o ativo e o maior para o passivo • Não autoriza reservas ocultas."},
{"m": "Contabilidade", "t": "Registro pelo valor original", "d": "Os componentes do patrimônio são registrados pelos valores originais das transações, expressos em moeda nacional • Base para o custo histórico."},
{"m": "Contabilidade", "t": "Características qualitativas fundamentais (CPC 00)", "d": "Relevância (inclui materialidade) e representação fidedigna (completa, neutra e livre de erro)."},
{"m": "Contabilidade", "t": "Características qualitativas de melhoria (CPC 00)", "d": "Comparabilidade, verificabilidade, tempestividade e compreensibilidade."},
{"m": "Contabilidade", "t": "DFC — três atividades", "d": "Operacionais (atividade principal: clientes, fornecedores, salários) • Investimento (compra/venda de imobilizado e participações) • Financiamento (empréstimos tomados, aporte de capital, dividendos pagos)."},
{"m": "Contabilidade", "t": "DFC — método direto", "d": "Mostra as entradas e saídas brutas de caixa das operações (recebimentos de clientes, pagamentos a fornecedores e empregados)."},
{"m": "Contabilidade", "t": "DFC — método indireto", "d": "Parte do lucro líquido e ajusta itens que não afetam o caixa (soma depreciação, amortização, perdas) e variações do capital de giro • Aumento de ativo circulante reduz caixa; aumento de passivo circulante aumenta."},
{"m": "Contabilidade", "t": "Liquidez corrente", "d": "Ativo circulante ÷ Passivo circulante • >1: bens e direitos de curto prazo cobrem as dívidas de curto prazo."},
{"m": "Contabilidade", "t": "Liquidez seca", "d": "(Ativo circulante − Estoques) ÷ Passivo circulante • Exclui os estoques, menos líquidos."},
{"m": "Contabilidade", "t": "Liquidez imediata", "d": "Disponibilidades (caixa + bancos + aplicações de liquidez imediata) ÷ Passivo circulante."},
{"m": "Contabilidade", "t": "Liquidez geral", "d": "(Ativo circulante + Realizável a longo prazo) ÷ (Passivo circulante + Passivo não circulante)."},
{"m": "Contabilidade", "t": "Capital circulante líquido (CCL)", "d": "Ativo circulante − Passivo circulante • Positivo indica folga financeira de curto prazo."},
{"m": "Contabilidade", "t": "Endividamento geral", "d": "(Passivo circulante + Passivo não circulante) ÷ Ativo total • Mostra quanto do ativo é financiado por terceiros."},
{"m": "Contabilidade", "t": "Fato permutativo, modificativo e misto", "d": "Permutativo: troca elementos sem alterar o PL (compra à vista de máquina) • Modificativo: altera o PL (pagamento de despesa) • Misto: troca e altera o PL ao mesmo tempo (receber duplicata com juros)."},
{"m": "Contabilidade", "t": "Provisão x reserva", "d": "Provisão: passivo de prazo ou valor incertos (ex.: provisão para contingências) • Reserva: parcela do PL, destinação de lucro (legal, estatutária)."},
{"m": "Contabilidade", "t": "Reserva legal (Lei 6.404, art. 193)", "d": "5% do lucro líquido do exercício, até atingir 20% do capital social."},
{"m": "Controle Patrimonial", "t": "Ativo imobilizado — conceito (CPC 27)", "d": "Bem tangível mantido para uso na produção, fornecimento de bens/serviços ou fins administrativos e que se espera usar por mais de um período (12 meses)."},
{"m": "Controle Patrimonial", "t": "Critérios para reconhecer um imobilizado", "d": "For provável que gere benefícios econômicos futuros para a entidade • O custo puder ser mensurado com confiabilidade."},
{"m": "Controle Patrimonial", "t": "Depreciação", "d": "Perda de valor de bens TANGÍVEIS do imobilizado pelo uso, desgaste ou obsolescência • ⚠ Terrenos não se depreciam."},
{"m": "Controle Patrimonial", "t": "Amortização x exaustão", "d": "Amortização: perda de valor de ativos INTANGÍVEIS de vida útil definida (softwares, marcas, direitos) • Exaustão: redução de recursos NATURAIS extraídos (minas, florestas, jazidas)."},
{"m": "Controle Patrimonial", "t": "Valor depreciável", "d": "Custo do bem − valor residual • É a base distribuída ao longo da vida útil."},
{"m": "Controle Patrimonial", "t": "Método linear (quotas constantes)", "d": "Depreciação anual = (custo − valor residual) ÷ vida útil • Mesma despesa todos os anos."},
{"m": "Controle Patrimonial", "t": "Método da soma dos dígitos dos anos", "d": "Soma os anos de vida útil (5 anos: 1+2+3+4+5 = 15) • Decrescente: 1º ano = 5/15, 2º = 4/15… do valor depreciável • Deprecia mais no início."},
{"m": "Controle Patrimonial", "t": "Método das unidades produzidas", "d": "Depreciação = valor depreciável × (unidades produzidas no período ÷ total estimado de unidades) • Varia com o uso."},
{"m": "Controle Patrimonial", "t": "Valor contábil (líquido) do bem", "d": "Custo de aquisição − depreciação acumulada − perdas por redução ao valor recuperável."},
{"m": "Controle Patrimonial", "t": "Impairment — teste de recuperabilidade (CPC 01)", "d": "Se o valor contábil superar o valor recuperável, reconhece-se perda • Valor recuperável = MAIOR entre valor justo líquido de despesas de venda e valor em uso."},
{"m": "Controle Patrimonial", "t": "Custo de aquisição do imobilizado", "d": "Preço de compra + tributos não recuperáveis + frete, instalação, montagem e gastos para colocar o bem em funcionamento • Descontos comerciais são deduzidos."},
{"m": "Controle Patrimonial", "t": "Gasto de capital x despesa de manutenção", "d": "Gasto que aumenta vida útil ou capacidade do bem é capitalizado (soma ao ativo) • Manutenção rotineira é despesa do período."},
{"m": "Controle Patrimonial", "t": "Tombamento / plaqueta patrimonial", "d": "Registro e identificação individual do bem com número patrimonial único, no momento da incorporação ao patrimônio."},
{"m": "Controle Patrimonial", "t": "Inventário físico — periódico x rotativo", "d": "Periódico (geral): contagem de todos os bens numa data, geralmente anual • Rotativo: contagens parciais e contínuas ao longo do ano, sem parar a operação."},
{"m": "Controle Patrimonial", "t": "Baixa patrimonial", "d": "Retirada do bem do registro por alienação (venda, doação), perda, roubo, obsolescência ou inservibilidade • Exige documento que comprove o motivo."},
{"m": "Controle Patrimonial", "t": "Bem inservível — classificações", "d": "Ocioso (em condições de uso, mas sem aproveitamento) • Recuperável (conserto viável) • Antieconômico (manutenção onerosa) • Irrecuperável (sem condições de uso)."},
{"m": "Controle Patrimonial", "t": "Manutenção corretiva", "d": "Feita após a falha ou queda de desempenho • Não planejada (emergencial) ou planejada (decide-se operar até falhar)."},
{"m": "Controle Patrimonial", "t": "Manutenção preventiva", "d": "Feita em intervalos predefinidos de TEMPO ou USO, para reduzir a probabilidade de falha, mesmo sem sintoma."},
{"m": "Controle Patrimonial", "t": "Manutenção preditiva", "d": "Baseada no monitoramento da CONDIÇÃO do equipamento (vibração, temperatura, análise de óleo, termografia) • Intervém só quando o parâmetro indica necessidade."},
{"m": "Controle Patrimonial", "t": "Manutenção detectiva", "d": "Busca falhas OCULTAS em sistemas de proteção/comando que não se manifestam na operação normal (ex.: testar alarme, válvula de segurança)."},
{"m": "Controle Patrimonial", "t": "Engenharia de manutenção", "d": "Atua nas causas básicas, analisa falhas e modifica projetos/rotinas para eliminar falhas crônicas • Nível mais avançado da manutenção."},
{"m": "Controle Patrimonial", "t": "MTBF", "d": "Mean Time Between Failures — tempo médio ENTRE falhas • Mede a CONFIABILIDADE • Quanto maior, melhor."},
{"m": "Controle Patrimonial", "t": "MTTR", "d": "Mean Time To Repair — tempo médio para REPARO • Mede a MANUTENIBILIDADE • Quanto menor, melhor."},
{"m": "Controle Patrimonial", "t": "Disponibilidade de um equipamento", "d": "MTBF ÷ (MTBF + MTTR) • Percentual do tempo em que o equipamento está apto a operar."},
{"m": "Controle Patrimonial", "t": "OEE — Eficiência Global do Equipamento", "d": "Disponibilidade × Desempenho (performance) × Qualidade • Referência de classe mundial ≈ 85%."},
{"m": "Controle Patrimonial", "t": "TPM — Manutenção Produtiva Total", "d": "Envolve todos, inclusive operadores (manutenção autônoma) • Meta: quebra zero, defeito zero, acidente zero • Estruturada em 8 pilares."},
{"m": "Controle Patrimonial", "t": "PCM — Planejamento e Controle da Manutenção", "d": "Programa, prioriza e controla as ordens de serviço, materiais, mão de obra e o histórico dos equipamentos."},
{"m": "Gestão de Sistemas Integrados", "t": "Sistema de Gestão Integrado (SGI)", "d": "Integra em uma só estrutura qualidade (ISO 9001), meio ambiente (ISO 14001) e saúde e segurança do trabalho (ISO 45001) • Reduz duplicidade de documentos e auditorias."},
{"m": "Gestão de Sistemas Integrados", "t": "ISO 9001", "d": "Sistema de gestão da QUALIDADE • Foco na satisfação do cliente e na melhoria contínua • Certificável."},
{"m": "Gestão de Sistemas Integrados", "t": "ISO 14001", "d": "Sistema de gestão AMBIENTAL • Controle de aspectos e impactos ambientais • Certificável."},
{"m": "Gestão de Sistemas Integrados", "t": "ISO 45001", "d": "Sistema de gestão de SAÚDE E SEGURANÇA ocupacional • Substituiu a OHSAS 18001 • Certificável."},
{"m": "Gestão de Sistemas Integrados", "t": "ISO 31000", "d": "Diretrizes de gestão de RISCOS • ⚠ NÃO é certificável (é guia)."},
{"m": "Gestão de Sistemas Integrados", "t": "ISO 19011", "d": "Diretrizes para AUDITORIA de sistemas de gestão • Não certificável."},
{"m": "Gestão de Sistemas Integrados", "t": "ISO 26000 / ISO 50001 / ISO 37001", "d": "26000: responsabilidade social (diretriz, não certificável) • 50001: gestão de energia • 37001: sistema antissuborno."},
{"m": "Gestão de Sistemas Integrados", "t": "Estrutura de alto nível (Anexo SL / HLS)", "d": "Mesma estrutura de 10 cláusulas para todas as normas ISO de sistema de gestão • Facilita a integração do SGI."},
{"m": "Gestão de Sistemas Integrados", "t": "Ciclo PDCA", "d": "Plan (planejar metas e métodos) • Do (executar e treinar) • Check (verificar resultados) • Act (agir corretivamente e padronizar) • Base da melhoria contínua."},
{"m": "Gestão de Sistemas Integrados", "t": "Os 7 princípios da gestão da qualidade (ISO 9000)", "d": "Foco no cliente • Liderança • Engajamento das pessoas • Abordagem de processo • Melhoria • Tomada de decisão baseada em evidência • Gestão de relacionamento."},
{"m": "Gestão de Sistemas Integrados", "t": "Gestão de riscos — conceito", "d": "Atividades coordenadas para dirigir e controlar a organização no que se refere a riscos • Risco = efeito da incerteza nos objetivos (pode ser negativo ou positivo)."},
{"m": "Gestão de Sistemas Integrados", "t": "Processo de gestão de riscos (ISO 31000)", "d": "Estabelecer o contexto → Identificar → Analisar → Avaliar os riscos → Tratar • Com comunicação/consulta e monitoramento/análise crítica contínuos."},
{"m": "Gestão de Sistemas Integrados", "t": "Tratamento de riscos — opções", "d": "Evitar (não realizar a atividade) • Mitigar/reduzir (diminuir probabilidade ou impacto) • Transferir/compartilhar (seguro, terceirização) • Aceitar/reter (assumir conscientemente)."},
{"m": "Gestão de Sistemas Integrados", "t": "Matriz de riscos", "d": "Cruza PROBABILIDADE (chance de ocorrer) com IMPACTO (consequência) para priorizar o tratamento dos riscos."},
{"m": "Gestão de Sistemas Integrados", "t": "Correção x ação corretiva", "d": "Correção: elimina a não conformidade detectada (conserta o produto) • Ação corretiva: elimina a CAUSA para evitar que se repita."},
{"m": "Gestão de Sistemas Integrados", "t": "Não conformidade", "d": "Não atendimento a um requisito (da norma, do cliente, legal ou interno) • Pode ser maior (sistêmica/grave) ou menor (pontual)."},
{"m": "Gestão de Sistemas Integrados", "t": "Auditoria de 1ª, 2ª e 3ª parte", "d": "1ª: interna, a própria organização • 2ª: cliente audita o fornecedor • 3ª: organismo certificador independente."},
{"m": "Gestão de Sistemas Integrados", "t": "Auditoria interna — finalidade", "d": "Verificar se o sistema de gestão está conforme os requisitos e eficazmente implementado • Auditor não deve auditar o próprio trabalho (independência)."},
{"m": "Gestão de Sistemas Integrados", "t": "Diagrama de Ishikawa (espinha de peixe)", "d": "Organiza as possíveis CAUSAS de um efeito/problema • Categorias 6M: método, máquina, mão de obra, material, meio ambiente, medida."},
{"m": "Gestão de Sistemas Integrados", "t": "Gráfico de Pareto", "d": "Barras em ordem decrescente com curva acumulada • Princípio 80/20: poucas causas vitais geram a maioria dos problemas • Serve para PRIORIZAR."},
{"m": "Gestão de Sistemas Integrados", "t": "5W2H", "d": "Plano de ação: What (o quê), Why (por quê), Where (onde), When (quando), Who (quem), How (como), How much (quanto custa)."},
{"m": "Gestão de Sistemas Integrados", "t": "5 Porquês", "d": "Pergunta \"por quê?\" sucessivamente (cerca de 5 vezes) até chegar à causa raiz de um problema."},
{"m": "Gestão de Sistemas Integrados", "t": "Folha de verificação, histograma e dispersão", "d": "Folha de verificação: coleta organizada de dados • Histograma: distribuição de frequência • Diagrama de dispersão: relação entre duas variáveis."},
{"m": "Gestão de Sistemas Integrados", "t": "Carta (gráfico) de controle", "d": "Acompanha um processo no tempo com limites superior e inferior de controle • Distingue causas comuns (aleatórias) de causas especiais (assinaláveis)."},
{"m": "Gestão de Sistemas Integrados", "t": "Programa 5S", "d": "Seiri (utilização/descarte) • Seiton (organização/ordem) • Seiso (limpeza) • Seiketsu (padronização/saúde) • Shitsuke (disciplina/autodisciplina)."},
{"m": "Gestão de Sistemas Integrados", "t": "Kaizen x inovação (kairyo)", "d": "Kaizen: melhoria contínua, gradual, de baixo custo e com participação de todos • Inovação: mudança radical, em saltos, geralmente com alto investimento."},
{"m": "Gestão de Sistemas Integrados", "t": "Six Sigma — DMAIC", "d": "Define • Measure • Analyze • Improve • Control • Meta de 3,4 defeitos por milhão de oportunidades."},
{"m": "Gestão de Sistemas Integrados", "t": "Eficiência x eficácia x efetividade", "d": "Eficiência: fazer certo, com o menor uso de recursos (meios) • Eficácia: atingir o resultado/meta (fins) • Efetividade: impacto real gerado (eficiente + eficaz + transformação)."},
{"m": "Gestão de Sistemas Integrados", "t": "Indicadores — KPI e metas SMART", "d": "KPI = indicador-chave de desempenho • Metas SMART: Específicas, Mensuráveis, Atingíveis, Relevantes e Temporais (com prazo)."},
{"m": "Gestão de Sistemas Integrados", "t": "Balanced Scorecard (BSC) — 4 perspectivas", "d": "Financeira • Clientes • Processos internos • Aprendizado e crescimento • Traduz a estratégia em indicadores ligados por relações de causa e efeito."},
{"m": "Gestão de Sistemas Integrados", "t": "ESG", "d": "Environmental (ambiental), Social e Governance (governança) • Critérios de sustentabilidade e responsabilidade usados por investidores e empresas."},
{"m": "Gestão de Sistemas Integrados", "t": "Tripé da sustentabilidade (Triple Bottom Line)", "d": "Equilíbrio entre os pilares econômico (lucro), social (pessoas) e ambiental (planeta) • Conceito de John Elkington."},
{"m": "Administração de RH / Processos Administrativos", "t": "Funções administrativas (PODC)", "d": "Planejar (definir objetivos) • Organizar (estruturar recursos e tarefas) • Dirigir (liderar, motivar, comunicar) • Controlar (medir e corrigir o desempenho)."},
{"m": "Administração de RH / Processos Administrativos", "t": "Níveis organizacionais", "d": "Estratégico: alta direção, longo prazo, organização toda • Tático: gerência média, médio prazo, departamentos • Operacional: supervisão, curto prazo, tarefas."},
{"m": "Administração de RH / Processos Administrativos", "t": "Estrutura linear", "d": "Autoridade única e direta (unidade de comando) • Simples e clara, mas rígida e sobrecarrega a chefia • Origem militar."},
{"m": "Administração de RH / Processos Administrativos", "t": "Estrutura funcional", "d": "Autoridade dividida por especialidade: o subordinado responde a vários chefes especialistas • Taylor • Risco: perda da unidade de comando."},
{"m": "Administração de RH / Processos Administrativos", "t": "Estrutura linha-staff", "d": "Linha tem autoridade de comando (decide) • Staff (assessoria) presta consultoria especializada, sem comando sobre a linha."},
{"m": "Administração de RH / Processos Administrativos", "t": "Estrutura matricial", "d": "Combina departamentalização funcional e por projetos • Dupla subordinação (gerente funcional e gerente de projeto)."},
{"m": "Administração de RH / Processos Administrativos", "t": "Centralização x descentralização", "d": "Centralização: decisões concentradas no topo (uniformidade, controle) • Descentralização: decisões delegadas aos níveis inferiores (agilidade, motivação)."},
{"m": "Administração de RH / Processos Administrativos", "t": "Recrutamento interno", "d": "Busca candidatos dentro da empresa (promoção, transferência) • Vantagens: mais rápido, barato, motiva e aproveita quem já conhece a cultura • Desvantagem: não renova ideias, pode gerar conflitos."},
{"m": "Administração de RH / Processos Administrativos", "t": "Recrutamento externo", "d": "Busca candidatos no mercado • Vantagens: traz novas ideias e experiências, renova a cultura • Desvantagens: mais caro, demorado e pode desmotivar os internos."},
{"m": "Administração de RH / Processos Administrativos", "t": "Recrutamento misto", "d": "Combina fontes internas e externas para a mesma vaga, aproveitando as vantagens de ambas."},
{"m": "Administração de RH / Processos Administrativos", "t": "Seleção de pessoas — conceito", "d": "Escolher, entre os candidatos recrutados, o mais adequado ao cargo, comparando requisitos do cargo com características do candidato."},
{"m": "Administração de RH / Processos Administrativos", "t": "Técnicas de seleção", "d": "Entrevista • Provas de conhecimento/capacidade • Testes psicológicos (aptidões) • Testes de personalidade • Técnicas de simulação (dinâmicas, role playing)."},
{"m": "Administração de RH / Processos Administrativos", "t": "Entrevista estruturada (padronizada)", "d": "Mesmas perguntas, na mesma ordem, para todos os candidatos • Mais objetiva e comparável; reduz a subjetividade do entrevistador."},
{"m": "Administração de RH / Processos Administrativos", "t": "Ciclo do treinamento", "d": "1) Diagnóstico — levantamento de necessidades (LNT) • 2) Desenho/programação • 3) Implementação/execução • 4) Avaliação dos resultados."},
{"m": "Administração de RH / Processos Administrativos", "t": "Levantamento de Necessidades de Treinamento (LNT)", "d": "Identifica a lacuna entre as competências exigidas pelo cargo e as que o empregado possui • Sem ele, o treinamento pode não atacar o problema real."},
{"m": "Administração de RH / Processos Administrativos", "t": "Modelo de Kirkpatrick — avaliação de treinamento", "d": "Nível 1 Reação (satisfação) • Nível 2 Aprendizagem (conhecimento adquirido) • Nível 3 Comportamento (aplicação no trabalho) • Nível 4 Resultados (impacto na organização)."},
{"m": "Administração de RH / Processos Administrativos", "t": "Treinamento x desenvolvimento", "d": "Treinamento: foco no cargo ATUAL, curto prazo • Desenvolvimento: foco em cargos FUTUROS e no crescimento da pessoa, longo prazo."},
{"m": "Administração de RH / Processos Administrativos", "t": "Carreira em Y", "d": "Após certo ponto, o empregado escolhe entre a trilha gerencial e a trilha técnica (especialista), com crescimento e remuneração equivalentes."},
{"m": "Administração de RH / Processos Administrativos", "t": "Promoção (ascensão vertical)", "d": "Mudança para cargo de nível hierárquico superior, com mais responsabilidade e remuneração, na mesma linha de carreira."},
{"m": "Administração de RH / Processos Administrativos", "t": "Transferência, job rotation e enriquecimento de cargo", "d": "Transferência/rotação: movimentos horizontais, sem subir de nível • Enriquecimento vertical: acrescenta responsabilidades de nível mais alto ao mesmo cargo."},
{"m": "Administração de RH / Processos Administrativos", "t": "Avaliação 360 graus", "d": "O avaliado recebe feedback de todos ao redor: chefe, colegas, subordinados, clientes e autoavaliação."},
{"m": "Administração de RH / Processos Administrativos", "t": "Método de escolha forçada", "d": "O avaliador escolhe, em blocos de frases, a que MAIS e a que MENOS descreve o avaliado • Reduz a influência pessoal (halo)."},
{"m": "Administração de RH / Processos Administrativos", "t": "Método dos incidentes críticos", "d": "Registra comportamentos extremamente positivos ou negativos do avaliado • Foca nas exceções, não no desempenho normal."},
{"m": "Administração de RH / Processos Administrativos", "t": "Escalas gráficas", "d": "Avalia fatores predefinidos (produtividade, qualidade…) em graus de uma escala • Método mais usado e simples, sujeito a efeito halo."},
{"m": "Administração de RH / Processos Administrativos", "t": "Avaliação por objetivos (APO)", "d": "Metas definidas em conjunto por gestor e empregado; a avaliação compara os resultados alcançados com as metas."},
{"m": "Administração de RH / Processos Administrativos", "t": "Efeito halo", "d": "Erro de avaliação: uma característica marcante (boa ou ruim) contamina a avaliação de todos os outros fatores."},
{"m": "Administração de RH / Processos Administrativos", "t": "Tendência central, leniência e recência", "d": "Tendência central: notas sempre medianas • Leniência/severidade: notas sistematicamente altas/baixas • Recência: considera só os fatos mais recentes."},
{"m": "Administração de RH / Processos Administrativos", "t": "Hierarquia das necessidades de Maslow", "d": "Da base ao topo: fisiológicas → segurança → sociais → estima → autorrealização • Necessidade satisfeita deixa de motivar."},
{"m": "Administração de RH / Processos Administrativos", "t": "Teoria dos dois fatores de Herzberg", "d": "Higiênicos (extrínsecos: salário, condições, chefia) evitam insatisfação, mas não motivam • Motivacionais (intrínsecos: reconhecimento, responsabilidade, o trabalho em si) geram satisfação."},
{"m": "Administração de RH / Processos Administrativos", "t": "Teoria X e Y de McGregor", "d": "X: pessoas são preguiçosas e precisam de controle • Y: pessoas gostam de trabalhar, são criativas e buscam responsabilidade."},
{"m": "Administração de RH / Processos Administrativos", "t": "Rotatividade (turnover)", "d": "Fluxo de entradas e saídas de pessoal • Fórmula usual: [(admissões + desligamentos) ÷ 2] ÷ efetivo médio × 100."},
{"m": "Administração de RH / Processos Administrativos", "t": "Absenteísmo", "d": "Ausências ao trabalho (faltas, atrasos) em relação ao tempo previsto de trabalho • Indicador de clima e saúde ocupacional."},
{"m": "Administração de RH / Processos Administrativos", "t": "Cultura x clima organizacional", "d": "Cultura: valores, crenças e normas compartilhados, profundos e duradouros • Clima: percepção momentânea dos empregados sobre o ambiente de trabalho."},
{"m": "Administração de RH / Processos Administrativos", "t": "Férias (CLT)", "d": "30 dias corridos após cada 12 meses de trabalho (período aquisitivo), concedidos nos 12 meses seguintes (concessivo) • Adicional de 1/3 • Podem ser divididas em até 3 períodos (um ≥ 14 dias; demais ≥ 5)."},
{"m": "Administração de RH / Processos Administrativos", "t": "Jornada e hora extra (CLT/CF)", "d": "Limite de 8 h diárias e 44 h semanais • Hora extra: no máximo 2 h por dia, com adicional mínimo de 50%."},
{"m": "Administração de RH / Processos Administrativos", "t": "Adicional noturno (trabalhador urbano)", "d": "Trabalho entre 22 h e 5 h • Adicional mínimo de 20% • Hora noturna reduzida de 52 min 30 s."},
{"m": "Administração de RH / Processos Administrativos", "t": "Insalubridade x periculosidade", "d": "Insalubridade: 10%, 20% ou 40% (graus mínimo, médio, máximo) sobre o salário mínimo • Periculosidade: 30% sobre o salário-base • Não se acumulam (escolhe-se um)."},
{"m": "Administração de RH / Processos Administrativos", "t": "Aviso prévio", "d": "Mínimo de 30 dias, acrescido de 3 dias por ano trabalhado na mesma empresa, até o total de 90 dias."},
{"m": "Administração de RH / Processos Administrativos", "t": "FGTS e 13º salário", "d": "FGTS: depósito mensal de 8% da remuneração pelo empregador • 13º: 1/12 da remuneração de dezembro por mês trabalhado, em duas parcelas."},
{"m": "Administração de RH / Processos Administrativos", "t": "Gestão documental — fases do arquivo (teoria das 3 idades)", "d": "Corrente (uso frequente, no setor) • Intermediário (uso eventual, aguarda prazo) • Permanente (valor histórico, guarda definitiva)."},
{"m": "Logística e Cadeia de Suprimentos", "t": "Modal rodoviário", "d": "Mais flexível, entrega porta a porta • Indicado para curtas e médias distâncias e cargas fracionadas • Custo fixo baixo e variável alto • Predominante no Brasil."},
{"m": "Logística e Cadeia de Suprimentos", "t": "Modal ferroviário", "d": "Grandes volumes de baixo valor agregado (minério, grãos) em longas distâncias • Custo fixo alto e variável baixo • Pouca flexibilidade."},
{"m": "Logística e Cadeia de Suprimentos", "t": "Modal aquaviário — cabotagem x longo curso", "d": "Cabotagem: entre portos do MESMO país, pela costa • Longo curso: entre portos de países diferentes • Navegação interior: rios e lagos (hidroviário)."},
{"m": "Logística e Cadeia de Suprimentos", "t": "Modal dutoviário", "d": "Transporte contínuo de líquidos e gases (petróleo, derivados, gás) por dutos • Custo fixo altíssimo e variável muito baixo • Seguro e pouco flexível • Atividade central da Transpetro."},
{"m": "Logística e Cadeia de Suprimentos", "t": "Modal aéreo", "d": "O mais rápido e o mais caro • Indicado para cargas de alto valor agregado, urgentes, perecíveis e de pequeno volume."},
{"m": "Logística e Cadeia de Suprimentos", "t": "Intermodal x multimodal", "d": "Intermodal: mais de um modal, com um documento/contrato para CADA trecho • Multimodal: um ÚNICO documento (CTMC) e um único responsável, o OTM (Operador de Transporte Multimodal)."},
{"m": "Logística e Cadeia de Suprimentos", "t": "Curva ABC de estoques", "d": "Classe A: poucos itens (~20%) com a maior parte do valor (~80%) — controle rigoroso • B: intermediária • C: muitos itens de pouco valor — controle simples • Base: Pareto."},
{"m": "Logística e Cadeia de Suprimentos", "t": "Lote econômico de compra (LEC)", "d": "LEC = √(2·D·Cp ÷ Ca) • D = demanda anual, Cp = custo de cada pedido, Ca = custo anual de manter uma unidade • Minimiza a soma dos custos de pedir e de estocar."},
{"m": "Logística e Cadeia de Suprimentos", "t": "Ponto de pedido (ponto de reposição)", "d": "PP = demanda média × tempo de reposição (lead time) + estoque de segurança • Atingido esse nível, emite-se novo pedido."},
{"m": "Logística e Cadeia de Suprimentos", "t": "Estoque de segurança", "d": "Estoque mínimo para absorver variações de demanda e atrasos no tempo de reposição, evitando a ruptura (falta)."},
{"m": "Logística e Cadeia de Suprimentos", "t": "Estoque médio", "d": "Lote de compra ÷ 2 + estoque de segurança."},
{"m": "Logística e Cadeia de Suprimentos", "t": "Giro e cobertura de estoque", "d": "Giro = demanda (ou consumo) no período ÷ estoque médio (vezes que o estoque se renova) • Cobertura = estoque médio ÷ demanda × período (tempo que o estoque dura)."},
{"m": "Logística e Cadeia de Suprimentos", "t": "PEPS, UEPS e custo médio", "d": "PEPS (FIFO): sai o mais antigo, estoque final fica com custos recentes • UEPS (LIFO): sai o mais recente — não aceito pelo Fisco nem pelas normas brasileiras • Média ponderada móvel: recalcula o custo a cada entrada."},
{"m": "Logística e Cadeia de Suprimentos", "t": "Just in time (JIT)", "d": "Produzir/comprar só o necessário, na quantidade e no momento certos • Estoques mínimos e eliminação de desperdícios • Origem: Toyota."},
{"m": "Logística e Cadeia de Suprimentos", "t": "Kanban", "d": "Sistema de sinalização visual (cartões) que \"puxa\" a produção/reposição conforme o consumo • Ferramenta do JIT."},
{"m": "Logística e Cadeia de Suprimentos", "t": "MRP x MRP II x ERP", "d": "MRP: calcula necessidades de materiais a partir do plano mestre e da lista de materiais • MRP II: inclui capacidade, mão de obra, finanças • ERP: integra todos os setores da empresa."},
{"m": "Logística e Cadeia de Suprimentos", "t": "VMI — estoque gerenciado pelo fornecedor", "d": "O fornecedor monitora o estoque do cliente e decide quando e quanto repor."},
{"m": "Logística e Cadeia de Suprimentos", "t": "Cross-docking", "d": "Mercadoria recebida é separada e expedida quase imediatamente, sem armazenagem prolongada • Reduz custos de estocagem."},
{"m": "Logística e Cadeia de Suprimentos", "t": "Efeito chicote (bullwhip)", "d": "Distorção da demanda que se amplifica à medida que sobe na cadeia (varejo → atacado → fábrica → fornecedor) • Combatido com compartilhamento de informação."},
{"m": "Logística e Cadeia de Suprimentos", "t": "Porta-paletes convencional", "d": "Acesso direto e seletivo a 100% dos paletes • Menor densidade de armazenagem."},
{"m": "Logística e Cadeia de Suprimentos", "t": "Drive-in x drive-through", "d": "Drive-in: uma só entrada, empilhadeira entra na estrutura — UEPS/LIFO, alta densidade • Drive-through: entrada e saída por lados opostos — PEPS/FIFO."},
{"m": "Logística e Cadeia de Suprimentos", "t": "Flow rack (dinâmico) e push-back", "d": "Flow rack: roletes inclinados, carga desliza por gravidade — FIFO • Push-back: palete empurrado para trás pelo seguinte — LIFO."},
{"m": "Logística e Cadeia de Suprimentos", "t": "WMS x TMS", "d": "WMS (Warehouse Management System): gerencia o armazém (endereçamento, picking, inventário) • TMS (Transportation Management System): gerencia o transporte (rotas, fretes, frota)."},
{"m": "Logística e Cadeia de Suprimentos", "t": "Picking", "d": "Separação dos itens do pedido no armazém • Modalidades: discreto (pedido a pedido), por lote, por zona e por onda."},
{"m": "Logística e Cadeia de Suprimentos", "t": "Unitização de cargas", "d": "Agrupar volumes em uma unidade maior e padronizada (palete, contêiner) para facilitar movimentação, armazenagem e transporte."},
{"m": "Logística e Cadeia de Suprimentos", "t": "Equipamentos de movimentação", "d": "Empilhadeira (eleva e transporta) • Transpaleteira/paleteira (movimenta paletes no plano) • Esteiras/transportadores contínuos • Pontes rolantes • AGV (veículo guiado automaticamente)."},
{"m": "Logística e Cadeia de Suprimentos", "t": "Embalagem primária, secundária e terciária", "d": "Primária: contato direto com o produto • Secundária: agrupa as primárias (caixa) • Terciária: para transporte e armazenagem (palete, contêiner)."},
{"m": "Logística e Cadeia de Suprimentos", "t": "Logística reversa", "d": "Retorno de produtos/materiais da ponta ao início da cadeia • Pós-venda: devoluções, defeitos, recalls • Pós-consumo: fim de vida útil, reciclagem, descarte adequado."},
{"m": "Logística e Cadeia de Suprimentos", "t": "Logística verde (sustentável)", "d": "Reduz impactos ambientais da logística: roteirização eficiente, modais menos poluentes, embalagens recicláveis, logística reversa."},
{"m": "Logística e Cadeia de Suprimentos", "t": "Operadores logísticos — 3PL e 4PL", "d": "3PL: terceiriza a execução de atividades logísticas (transporte, armazenagem) • 4PL: integra e gerencia toda a cadeia, coordenando vários 3PL."},
{"m": "Logística e Cadeia de Suprimentos", "t": "Cadeia de suprimentos (supply chain)", "d": "Rede de empresas e processos que vai dos fornecedores de matéria-prima até o cliente final, integrando fluxos de materiais, informação e dinheiro."},
{"m": "Logística e Cadeia de Suprimentos", "t": "Matriz de Kraljic (compras)", "d": "Cruza impacto no lucro × risco de suprimento • Itens estratégicos (alto/alto) • Alavancáveis (alto impacto, baixo risco) • Gargalo (baixo impacto, alto risco) • Não críticos (baixo/baixo)."},
{"m": "Logística e Cadeia de Suprimentos", "t": "Compras centralizadas x descentralizadas", "d": "Centralizadas: maior poder de negociação, padronização e controle • Descentralizadas: mais agilidade e atendimento às necessidades locais."},
{"m": "Logística e Cadeia de Suprimentos", "t": "Follow-up de compras / diligenciamento", "d": "Acompanhamento do pedido junto ao fornecedor para garantir prazo, quantidade e qualidade da entrega."},
{"m": "Logística e Cadeia de Suprimentos", "t": "Qualificação e avaliação de fornecedores", "d": "Qualificação: verificar antes de contratar se o fornecedor atende aos requisitos (técnicos, legais, financeiros) • Avaliação (IDF): medir o desempenho nas entregas."},
{"m": "Logística e Cadeia de Suprimentos", "t": "Incoterms — EXW x FOB x CIF x DDP", "d": "EXW: comprador assume tudo desde o estabelecimento do vendedor • FOB: risco passa ao comprador a bordo do navio • CIF: vendedor paga frete e seguro até o destino • DDP: vendedor entrega com tudo pago, inclusive impostos."},
{"m": "Legislação", "t": "Lei que rege as licitações da Transpetro", "d": "Lei 13.303/2016 (Lei das Estatais), aplicável a empresas públicas, sociedades de economia mista e suas subsidiárias • ⚠ A Lei 14.133/2021 NÃO se aplica às estatais, salvo os crimes (art. 178), conforme seu art. 1º, §1º."},
{"m": "Legislação", "t": "Lei 13.303 — objetivos da licitação (art. 31)", "d": "Assegurar a seleção da proposta mais vantajosa, inclusive quanto ao ciclo de vida do objeto, e evitar sobrepreço e superfaturamento."},
{"m": "Legislação", "t": "Lei 13.303 — licitação dispensável por valor (art. 29, I e II)", "d": "Obras e serviços de engenharia até R$ 100.000 • Outros serviços e compras até R$ 50.000 • Valores podem ser atualizados pelo conselho de administração."},
{"m": "Legislação", "t": "Lei 13.303 — inexigibilidade (art. 30)", "d": "Inviabilidade de competição, em especial: fornecedor/produtor EXCLUSIVO e serviços técnicos especializados de natureza singular com profissional/empresa de notória especialização (vedado para publicidade)."},
{"m": "Legislação", "t": "Lei 13.303 — dispensa de licitação do art. 28, §3º", "d": "Comercialização, prestação ou execução de produtos, serviços ou obras ligados ao OBJETO SOCIAL da estatal, e escolha de parceiro em OPORTUNIDADES DE NEGÓCIO definidas e específicas."},
{"m": "Legislação", "t": "Lei 13.303 — pregão (art. 32, IV)", "d": "Adoção PREFERENCIAL da modalidade pregão para aquisição de bens e serviços comuns."},
{"m": "Legislação", "t": "Lei 13.303 — sequência das fases (art. 51)", "d": "Preparação → divulgação → apresentação de lances/propostas → julgamento → verificação de efetividade dos lances → negociação → HABILITAÇÃO → recursos → adjudicação → homologação ou revogação/anulação • ⚠ Habilitação vem DEPOIS do julgamento (regra)."},
{"m": "Legislação", "t": "Lei 13.303 — modos de disputa (art. 52)", "d": "Aberto: lances públicos e sucessivos, crescentes ou decrescentes • Fechado: propostas sigilosas até a data de divulgação • Podem ser combinados."},
{"m": "Legislação", "t": "Lei 13.303 — critérios de julgamento (art. 54)", "d": "Menor preço • Maior desconto • Melhor combinação de técnica e preço • Melhor técnica • Melhor conteúdo artístico • Maior oferta de preço • Maior retorno econômico • Melhor destinação de bens alienados."},
{"m": "Legislação", "t": "Lei 13.303 — prazos mínimos para propostas (art. 39)", "d": "Bens: 5 dias úteis (menor preço/maior desconto) ou 10 dias úteis (demais) • Obras e serviços: 15 dias úteis (menor preço/maior desconto) ou 30 dias úteis (demais) • 45 dias úteis: melhor técnica, conteúdo artístico, contratação integrada ou semi-integrada."},
{"m": "Legislação", "t": "Lei 13.303 — orçamento sigiloso (art. 34)", "d": "O valor estimado do contrato é, em regra, SIGILOSO, sendo divulgado só após o encerramento da licitação • Pode ser público se houver justificativa • Sempre disponível aos órgãos de controle."},
{"m": "Legislação", "t": "Lei 13.303 — regimes de execução (art. 42/43)", "d": "Empreitada por preço unitário • Empreitada por preço global • Tarefa • Empreitada integral • Contratação semi-integrada • Contratação integrada."},
{"m": "Legislação", "t": "Lei 13.303 — procedimentos auxiliares (art. 63)", "d": "Pré-qualificação permanente • Cadastramento • Sistema de registro de preços • Catálogo eletrônico de padronização."},
{"m": "Legislação", "t": "Lei 13.303 — duração dos contratos (art. 71)", "d": "Até 5 anos, contados da celebração • Exceções: projetos do plano de negócios e investimentos e casos em que a pactuação por prazo superior seja prática rotineira de mercado • Vedado prazo indeterminado."},
{"m": "Legislação", "t": "Lei 13.303 — garantia contratual (art. 70)", "d": "Até 5% do valor do contrato • Até 10% para obras, serviços e fornecimentos de grande vulto e alta complexidade técnica • Modalidades: caução em dinheiro, seguro-garantia ou fiança bancária (escolha do contratado)."},
{"m": "Legislação", "t": "Lei 13.303 — alteração do contrato (art. 81)", "d": "Acréscimos ou supressões de até 25% do valor inicial atualizado • Até 50% para ACRÉSCIMOS em reforma de edifício ou equipamento • Supressões maiores só por acordo entre as partes."},
{"m": "Legislação", "t": "Lei 13.303 — sanções (art. 83)", "d": "Advertência • Multa (prevista no contrato) • Suspensão temporária de participar de licitação e impedimento de contratar com a entidade sancionadora por até 2 anos."},
{"m": "Legislação", "t": "Lei 13.303 — área de integridade (art. 9º)", "d": "Estatais devem ter regras de estrutura e práticas de gestão de riscos e controle interno: área de compliance/integridade, auditoria interna e Comitê de Auditoria Estatutário."},
{"m": "Legislação", "t": "Lei 14.133 — modalidades (art. 28)", "d": "Pregão • Concorrência • Concurso • Leilão • Diálogo competitivo • ⚠ Extintas: tomada de preços e convite."},
{"m": "Legislação", "t": "Lei 14.133 — pregão", "d": "Obrigatório para bens e serviços COMUNS • Critério: menor preço ou maior desconto • Não se aplica a serviços técnicos especializados intelectuais nem a obras (exceto serviços comuns de engenharia)."},
{"m": "Legislação", "t": "Lei 14.133 — concurso, leilão e diálogo competitivo", "d": "Concurso: trabalho técnico, científico ou artístico, com prêmio • Leilão: alienação de bens, maior lance • Diálogo competitivo: inovação, quando a Administração não consegue definir sozinha a solução."},
{"m": "Legislação", "t": "Lei 14.133 — critérios de julgamento (art. 33)", "d": "Menor preço • Maior desconto • Melhor técnica ou conteúdo artístico • Técnica e preço • Maior lance (leilão) • Maior retorno econômico."},
{"m": "Legislação", "t": "Lei 14.133 — sequência das fases (art. 17)", "d": "Preparatória → divulgação do edital → apresentação de propostas e lances → julgamento → habilitação → recursal → homologação • Habilitação pode ser antecipada por ato motivado."},
{"m": "Legislação", "t": "Lei 14.133 — inexigibilidade (art. 74)", "d": "Inviabilidade de competição: fornecedor exclusivo • Artista consagrado • Serviços técnicos especializados de notória especialização • Credenciamento • Compra/locação de imóvel cujas características tornem necessária sua escolha."},
{"m": "Legislação", "t": "Lei 14.133 — dispensa por valor (art. 75)", "d": "Obras/serviços de engenharia e manutenção de veículos: originalmente até R$ 100 mil • Outros serviços e compras: até R$ 50 mil • Valores atualizados anualmente por decreto."},
{"m": "Legislação", "t": "Lei 14.133 — agente de contratação (art. 8º)", "d": "Designado entre servidores efetivos ou empregados públicos permanentes para conduzir a licitação • No pregão, chama-se pregoeiro • Pode ser substituído por comissão de no mínimo 3 membros em casos específicos."},
{"m": "Legislação", "t": "Lei 14.133 — duração de contratos contínuos (arts. 106 e 107)", "d": "Serviços e fornecimentos contínuos: até 5 anos, prorrogáveis até o limite de 10 anos."},
{"m": "Legislação", "t": "Lei 14.133 — alteração do contrato (art. 125)", "d": "Acréscimos ou supressões unilaterais de até 25% • Até 50% para acréscimos em reforma de edifício ou equipamento."},
{"m": "Legislação", "t": "Lei 14.133 — garantias (arts. 96 a 99)", "d": "Caução em dinheiro ou títulos, seguro-garantia, fiança bancária ou título de capitalização • Até 5% (até 10% por complexidade) • Obras de grande vulto: seguro-garantia com cláusula de retomada até 30%."},
{"m": "Legislação", "t": "Lei 14.133 — sanções (art. 156)", "d": "Advertência • Multa (0,5% a 30% do valor do contrato) • Impedimento de licitar e contratar no ente sancionador, até 3 anos • Declaração de inidoneidade, em todos os entes, de 3 a 6 anos."},
{"m": "Legislação", "t": "Lei 14.133 — PNCP", "d": "Portal Nacional de Contratações Públicas: sítio eletrônico oficial para divulgação centralizada e obrigatória dos atos de licitações e contratos."},
{"m": "Informática", "t": "Windows 11 — Win + E / Win + D / Win + L", "d": "Win+E: abre o Explorador de Arquivos • Win+D: mostra/oculta a área de trabalho • Win+L: bloqueia o computador."},
{"m": "Informática", "t": "Windows 11 — Win + V / Win + Shift + S", "d": "Win+V: histórico da área de transferência • Win+Shift+S: Ferramenta de Captura (recorte de tela)."},
{"m": "Informática", "t": "Windows 11 — Win + I / Win + Tab / Win + Z", "d": "Win+I: Configurações • Win+Tab: Visão de Tarefas (áreas de trabalho virtuais) • Win+Z: layouts de Ajuste (Snap)."},
{"m": "Informática", "t": "Windows 11 — Ctrl + Shift + Esc e Alt + Tab", "d": "Ctrl+Shift+Esc: abre o Gerenciador de Tarefas diretamente • Alt+Tab: alterna entre janelas abertas."},
{"m": "Informática", "t": "Windows — Shift + Delete", "d": "Exclui o arquivo PERMANENTEMENTE, sem enviar para a Lixeira • Delete sozinho envia para a Lixeira."},
{"m": "Informática", "t": "Word (pt-BR) — Ctrl + N / I / S", "d": "Ctrl+N: Negrito • Ctrl+I: Itálico • Ctrl+S: Sublinhado • ⚠ Em português, salvar é Ctrl+B."},
{"m": "Informática", "t": "Word (pt-BR) — alinhamentos", "d": "Ctrl+Q: esquerda • Ctrl+E: centralizar • Ctrl+G: direita • Ctrl+J: justificar."},
{"m": "Informática", "t": "Word — F7, Shift + F3 e Ctrl + Enter", "d": "F7: verificar ortografia e gramática • Shift+F3: alternar maiúsculas/minúsculas • Ctrl+Enter: quebra de página."},
{"m": "Informática", "t": "PowerPoint — F5 x Shift + F5", "d": "F5: inicia a apresentação do PRIMEIRO slide • Shift+F5: inicia a partir do slide ATUAL."},
{"m": "Informática", "t": "Excel — referência relativa, absoluta e mista", "d": "A1: relativa (muda ao copiar) • $A$1: absoluta (fixa) • $A1 ou A$1: mista (fixa coluna ou linha) • F4 alterna entre os tipos."},
{"m": "Informática", "t": "Excel — PROCV", "d": "=PROCV(valor; matriz; nº da coluna; 0) • Procura na 1ª coluna da matriz e retorna da coluna indicada • 0/FALSO = correspondência exata."},
{"m": "Informática", "t": "Excel — PROCX", "d": "=PROCX(valor; matriz_procura; matriz_retorno) • Procura em qualquer direção (esquerda ou direita) e já usa correspondência exata por padrão."},
{"m": "Informática", "t": "Excel — SE, SOMASE e CONT.SE", "d": "=SE(teste; se_verdadeiro; se_falso) • =SOMASE(intervalo; critério; [soma]) soma o que atende ao critério • =CONT.SE(intervalo; critério) conta o que atende."},
{"m": "Informática", "t": "Excel — CONT.VALORES x CONT.NÚM x CONTAR.VAZIO", "d": "CONT.VALORES: conta células NÃO vazias (texto ou número) • CONT.NÚM: conta só números • CONTAR.VAZIO: conta células vazias."},
{"m": "Informática", "t": "Excel — mensagens de erro", "d": "#DIV/0!: divisão por zero • #N/D: valor não encontrado (PROCV) • #REF!: referência inválida/excluída • #VALOR!: tipo de dado errado • #NOME?: nome de função digitado errado."},
{"m": "Informática", "t": "Vírus x worm", "d": "Vírus: precisa de um arquivo hospedeiro e da execução para se propagar • Worm: se autorreplica pela rede SOZINHO, sem hospedeiro, consumindo recursos."},
{"m": "Informática", "t": "Cavalo de Troia (trojan)", "d": "Programa aparentemente legítimo que executa, escondido, funções maliciosas • Geralmente instala backdoor ou outros malwares."},
{"m": "Informática", "t": "Ransomware", "d": "Criptografa (sequestra) os dados da vítima e exige resgate, geralmente em criptomoeda • Principal defesa: backup atualizado e isolado."},
{"m": "Informática", "t": "Spyware, keylogger e adware", "d": "Spyware: monitora e envia informações do usuário • Keylogger: registra o que é digitado no teclado • Adware: exibe propaganda indesejada."},
{"m": "Informática", "t": "Rootkit, backdoor e botnet", "d": "Rootkit: esconde a presença do invasor/malware no sistema • Backdoor: porta dos fundos para acesso remoto • Botnet: rede de máquinas infectadas (zumbis) controladas remotamente."},
{"m": "Informática", "t": "Phishing", "d": "Golpe que usa mensagens/sites falsos que imitam instituições para roubar senhas e dados • Spear phishing: direcionado a uma pessoa/empresa específica."},
{"m": "Informática", "t": "Backup completo, incremental e diferencial", "d": "Completo: copia tudo • Incremental: só o que mudou desde o ÚLTIMO backup de qualquer tipo (rápido para fazer, lento para restaurar) • Diferencial: tudo o que mudou desde o último COMPLETO."},
{"m": "Informática", "t": "Pilares da segurança da informação (CID)", "d": "Confidencialidade (só autorizados acessam) • Integridade (não alterada indevidamente) • Disponibilidade (acessível quando necessário) • + Autenticidade e não repúdio."},
{"m": "Informática", "t": "Criptografia simétrica x assimétrica", "d": "Simétrica: UMA mesma chave cifra e decifra (rápida) • Assimétrica: par de chaves pública e privada (cifra com a pública do destinatário, decifra com a privada)."},
{"m": "Informática", "t": "Assinatura digital", "d": "Feita com a chave PRIVADA do remetente e verificada com a pública • Garante autenticidade, integridade e não repúdio • ⚠ Não garante confidencialidade."},
{"m": "Informática", "t": "Firewall", "d": "Filtra o tráfego entre redes conforme regras, bloqueando conexões não autorizadas • ⚠ Não é antivírus: não remove malware de arquivos."},
{"m": "Informática", "t": "Autenticação multifator (MFA)", "d": "Combina fatores de categorias diferentes: algo que você sabe (senha), algo que você tem (token, celular) e algo que você é (biometria)."},
{"m": "Informática", "t": "Protocolos de e-mail — SMTP, POP3, IMAP", "d": "SMTP: ENVIO de e-mails • POP3: recebe baixando para o dispositivo (em geral remove do servidor) • IMAP: recebe sincronizando, mensagens ficam no servidor."},
{"m": "Informática", "t": "HTTP x HTTPS / DNS / FTP", "d": "HTTPS: HTTP com criptografia TLS (cadeado) • DNS: traduz nomes de domínio em endereços IP • FTP: transferência de arquivos."},
{"m": "Informática", "t": "Internet, intranet e extranet", "d": "Internet: rede pública mundial • Intranet: rede privada da organização com tecnologia da internet • Extranet: parte da intranet acessível a parceiros externos autorizados."},
{"m": "Informática", "t": "Navegação anônima (privativa)", "d": "Não salva histórico, cookies e dados de formulário NO DISPOSITIVO após fechar • ⚠ Não esconde a navegação do provedor, da empresa ou dos sites."},
{"m": "Informática", "t": "Computação em nuvem — IaaS, PaaS, SaaS", "d": "IaaS: infraestrutura (servidores, armazenamento) • PaaS: plataforma para desenvolver apps • SaaS: software pronto via internet (Microsoft 365, Gmail)."},
{"m": "Informática", "t": "Memória RAM x ROM x armazenamento", "d": "RAM: principal, VOLÁTIL (perde dados ao desligar) • ROM: somente leitura, não volátil (firmware/BIOS) • SSD/HD: armazenamento permanente (SSD mais rápido, sem partes móveis)."},
{"m": "Informática", "t": "Hardware x software / periféricos", "d": "Hardware: parte física • Software: programas (sistema, aplicativo, utilitário) • Periféricos: entrada (teclado, mouse), saída (monitor, impressora), entrada e saída (touchscreen, multifuncional)."},
{"m": "Informática", "t": "LGPD — dado pessoal x dado pessoal sensível", "d": "Pessoal: identifica ou torna identificável uma pessoa natural • Sensível: origem racial/étnica, convicção religiosa, opinião política, filiação sindical, saúde, vida sexual, dado genético ou biométrico."},
{"m": "Informática", "t": "LGPD — dado anonimizado", "d": "Dado que não permite identificar o titular por meios técnicos razoáveis • Em regra, NÃO é considerado dado pessoal para a LGPD."},
{"m": "Informática", "t": "LGPD — controlador x operador", "d": "Controlador: toma as DECISÕES sobre o tratamento • Operador: realiza o tratamento EM NOME do controlador • Juntos são os agentes de tratamento."},
{"m": "Informática", "t": "LGPD — encarregado (DPO)", "d": "Pessoa indicada pelo controlador para ser o canal de comunicação entre controlador, titulares e a ANPD."},
{"m": "Informática", "t": "LGPD — ANPD", "d": "Autoridade Nacional de Proteção de Dados: órgão que fiscaliza, regulamenta e aplica as sanções da LGPD."},
{"m": "Informática", "t": "LGPD — bases legais (art. 7º)", "d": "10 hipóteses: consentimento • obrigação legal • políticas públicas • estudos por órgão de pesquisa • execução de contrato • exercício regular de direitos • proteção da vida • tutela da saúde • legítimo interesse • proteção do crédito."},
{"m": "Informática", "t": "LGPD — consentimento", "d": "Manifestação LIVRE, INFORMADA e INEQUÍVOCA do titular para finalidade determinada • Pode ser revogado a qualquer momento • Crianças: consentimento específico de pelo menos um dos pais."},
{"m": "Informática", "t": "LGPD — princípios (art. 6º)", "d": "Finalidade • adequação • necessidade (mínimo necessário) • livre acesso • qualidade dos dados • transparência • segurança • prevenção • não discriminação • responsabilização e prestação de contas."},
{"m": "Informática", "t": "LGPD — sanções da ANPD", "d": "Advertência • Multa simples de até 2% do faturamento, limitada a R$ 50 milhões por infração • Multa diária • Publicização • Bloqueio ou eliminação dos dados • Suspensão do tratamento."}
];
